#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Climbing Stairs: How many ways to reach step n?
int climbStairs(int n) {
    if (n <= 2) return n;
    vector<int> dp(n+1);
    dp[1] = 1; dp[2] = 2;
    for (int i = 3; i <= n; i++)
        dp[i] = dp[i-1] + dp[i-2];
    return dp[n];
}

// House Robber: Max money without robbing adjacent houses
int houseRobber(vector<int>& nums) {
    int n = nums.size();
    if (n == 1) return nums[0];
    vector<int> dp(n);
    dp[0] = nums[0];
    dp[1] = max(nums[0], nums[1]);
    for (int i = 2; i < n; i++)
        dp[i] = max(dp[i-1], dp[i-2] + nums[i]);
    return dp[n-1];
}

int main() {
    cout << "Climb(5): " << climbStairs(5) << endl; // 8
    vector<int> houses = {2, 7, 9, 3, 1};
    cout << "Rob: " << houseRobber(houses) << endl; // 12
    return 0;
}

