#include <stdio.h>

int climbStairs(int n) {
    if (n <= 2) return n;
    int dp[n+1];
    dp[1] = 1; dp[2] = 2;
    for (int i = 3; i <= n; i++)
        dp[i] = dp[i-1] + dp[i-2];
    return dp[n];
}

int houseRobber(int nums[], int n) {
    if (n == 1) return nums[0];
    int dp[n];
    dp[0] = nums[0];
    dp[1] = nums[0] > nums[1] ? nums[0] : nums[1];
    for (int i = 2; i < n; i++) {
        int pick = dp[i-2] + nums[i];
        dp[i] = pick > dp[i-1] ? pick : dp[i-1];
    }
    return dp[n-1];
}

int main() {
    printf("Climb(5): %d\n", climbStairs(5));
    int houses[] = {2, 7, 9, 3, 1};
    printf("Rob: %d\n", houseRobber(houses, 5));
    return 0;
}

