#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

// Unique Grid Paths
int uniquePaths(int m, int n) {
    vector<vector<int>> dp(m, vector<int>(n, 1));
    for (int i = 1; i < m; i++)
        for (int j = 1; j < n; j++)
            dp[i][j] = dp[i-1][j] + dp[i][j-1];
    return dp[m-1][n-1];
}

// Longest Common Subsequence
int lcs(string s1, string s2) {
    int m = s1.size(), n = s2.size();
    vector<vector<int>> dp(m+1, vector<int>(n+1, 0));
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++) {
            if (s1[i-1] == s2[j-1])
                dp[i][j] = 1 + dp[i-1][j-1];
            else
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
        }
    return dp[m][n];
}

int main() {
    cout << "Grid 3x3 paths: " << uniquePaths(3, 3) << endl; // 6
    cout << "LCS(abcde, ace): " << lcs("abcde", "ace") << endl; // 3
    return 0;
}

