#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// 0/1 Knapsack
int knapsack01(vector<int>& wt, vector<int>& val, int W) {
    int n = wt.size();
    vector<vector<int>> dp(n+1, vector<int>(W+1, 0));
    for (int i = 1; i <= n; i++)
        for (int w = 0; w <= W; w++) {
            dp[i][w] = dp[i-1][w]; // skip
            if (wt[i-1] <= w)
                dp[i][w] = max(dp[i][w], dp[i-1][w-wt[i-1]] + val[i-1]);
        }
    return dp[n][W];
}

// Unbounded Knapsack
int knapsackUnbounded(vector<int>& wt, vector<int>& val, int W) {
    vector<int> dp(W+1, 0);
    for (int w = 0; w <= W; w++)
        for (int i = 0; i < (int)wt.size(); i++)
            if (wt[i] <= w)
                dp[w] = max(dp[w], dp[w-wt[i]] + val[i]);
    return dp[W];
}

int main() {
    vector<int> wt = {1, 3, 4, 5};
    vector<int> val = {1, 4, 5, 7};
    int W = 7;
    cout << "0/1 Knapsack: " << knapsack01(wt, val, W) << endl;        // 9
    cout << "Unbounded: " << knapsackUnbounded(wt, val, W) << endl;    // 11
    return 0;
}

