#include <stdio.h>

int max(int a, int b) { return a > b ? a : b; }

int knapsack01(int wt[], int val[], int n, int W) {
    int dp[n+1][W+1];
    for (int i = 0; i <= n; i++)
        for (int w = 0; w <= W; w++) {
            if (i == 0 || w == 0) dp[i][w] = 0;
            else {
                dp[i][w] = dp[i-1][w];
                if (wt[i-1] <= w)
                    dp[i][w] = max(dp[i][w], dp[i-1][w-wt[i-1]] + val[i-1]);
            }
        }
    return dp[n][W];
}

int knapsackUnbounded(int wt[], int val[], int n, int W) {
    int dp[W+1];
    for (int w = 0; w <= W; w++) {
        dp[w] = 0;
        for (int i = 0; i < n; i++)
            if (wt[i] <= w)
                dp[w] = max(dp[w], dp[w-wt[i]] + val[i]);
    }
    return dp[W];
}

